grammar:
grammar Spaced {
  @whitespace: javaStyle
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  B ::= 'b' ;
}

grammar Commented {
  @comment: { line: '//' }
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  B ::= 'b' ;
}

grammar Gapped {
  @whitespace: GAP
  token GAP ::= '#'+;
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  B ::= 'b' ;
}

grammar SpacedConsuming {
  @whitespace: javaStyle
  token ANYC = ANY
  token ID ::= XID_IDENTIFIER;
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  B ::= 'b' ;
  P ::= '/' P | 'x' ;
  Q ::= ANYC Q | 'y' ;
  X ::= ID X | 'z' ;
}

grammar SpacedRuleNone {
  @whitespace: javaStyle
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  @whitespace(none)
  B ::= 'b' ;
}

grammar SpacedInterleave {
  @whitespace: javaStyle
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  @interleave(profile=commentsAndSpaces)
  B ::= 'b' ;
}

grammar SpacedContext {
  @whitespace: javaStyle
  token ID ::= 'b';
  @root
  Root ::= { S } ;
  @autoCommit
  S ::= 'k' B ;
  @lexicalContext(tokens=['ID'])
  B ::= ID ;
}

grammar Roots {
  @root @autoCommit
  A ::= 'a' N ;
  @root
  @autoCommit
  B ::= 'b' N ;
  N ::= 'n' ;
}

grammar Recover {
  @root
  Root ::= { S } ;
  @autoCommit @recovery(sync=';')
  S ::= 'k' N ';' ;
  N ::= 'n' ;
}

grammar Unused {
  @root
  Root ::= 'r' N ;
  @autoCommit
  Lost ::= 'l' N ;
  N ::= 'n' ;
}

grammar Kept {
  @root
  Root ::= Item 'x' | 'a' 'y' ;
  @autoCommit
  Item ::= 'a' B ;
  B ::= 'b' ;
}

